//! Regression test against OpenSubdiv itself: every shape of OpenSubdiv's
//! regression catalogue, refined and patched by this crate, compared with
//! reference results computed by OpenSubdiv 3.7.0.
//!
//! The data lives in `tests/data/upstream/` and is generated by
//! `tools/osd_reference/generate.sh` (see the README there). For each shape
//! it holds the base mesh (`<shape>.mesh`) and OpenSubdiv's results
//! (`<shape>.ref`):
//!
//! * uniform refinement: per-level vertex/edge/face counts, and a sample of
//!   last-level face corners with their refined position, limit position,
//!   UV and UV limit;
//! * adaptive patch tables (isolation 4, isolation 4 with single-crease
//!   patches, isolation 3 with face-varying patches; Gregory-basis end caps,
//!   `useInfSharpPatch` on): patch counts per type, and a sample of patch
//!   evaluations (position, du, dv, and UV).
//!
//! Refined components are numbered differently in this crate, so corners
//! are matched by position, not by index.
//!
//! Every known difference from OpenSubdiv is listed in [`KNOWN_DEVIATIONS`]
//! with the issue that tracks it. The test fails on any difference that is
//! not listed, and also on a listed difference that no longer occurs, so a
//! fix has to remove its entry.

use opensubdiv_rs::far::{
    AdaptiveOptions, FVarChannelDescriptor, PatchMap, PatchTableFactory, PatchTableOptions,
    PatchType, PrimvarRefiner, TopologyDescriptor, TopologyRefiner, TopologyRefinerFactory,
    UniformOptions,
};
use opensubdiv_rs::sdc::{
    self, CreasingMethod, FVarLinearInterpolation, SchemeType, TriangleSubdivision,
    VtxBoundaryInterpolation,
};
use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::fmt::Write as _;
use std::path::PathBuf;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Mutex;

/// What is compared, per shape.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum Check {
    /// `TopologyRefinerFactory::create` accepts the mesh.
    Create,
    /// Vertex, edge and face counts of every uniform level.
    UniformCounts,
    /// Refined positions at the last uniform level.
    UniformPositions,
    /// `PrimvarRefiner::limit` at the last uniform level.
    UniformLimit,
    /// Refined UVs at the last uniform level.
    UniformFVar,
    /// `PrimvarRefiner::limit_face_varying` at the last uniform level.
    UniformFVarLimit,
    /// Number of patches of each type.
    PatchCounts(Config),
    /// Patch positions; also whether a patch is found at all.
    PatchPositions(Config),
    /// First derivatives on B-spline and box-spline patches.
    PatchDerivatives(Config),
    /// Face-varying patch values.
    FVarPatches(Config),
}

/// The adaptive configurations of the reference data.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum Config {
    /// Isolation 4.
    Iso4,
    /// Isolation 4 with single-crease patches.
    Iso4SingleCrease,
    /// Isolation 3 with face-varying patches.
    Iso3FVar,
}

use Check::*;
use Config::*;

/// Known differences from OpenSubdiv 3.7.0: (shape, check, cause).
///
/// The cause is an issue number
/// (<https://github.com/doubleailes/OpenSubdiv-rs/issues>), a documented
/// deviation, or "undiagnosed":
///
/// * #32: Chaikin creasing averages infinitely sharp neighbour edges.
/// * #34: the Catmark limit mask at valence-2 vertices.
/// * #35: faces with a repeated vertex are rejected.
/// * #36: vertices used by no face are dropped from refined levels.
/// * #37: distinct edges between the same two vertices are merged.
/// * #39: `VtxBoundaryInterpolation::None` keeps the boundary faces.
/// * #40: smooth corners get Gregory caps (no legacy sharp-corner patches).
/// * #41: Gregory caps where unresolved semi-sharp creases leave the
///   topology regular.
/// * #43, #46: a different patch layout (sparse levels, isolation around
///   infinitely sharp and non-manifold features); same surface.
/// * single-crease: the documented single-crease deviation (README): this
///   crate evaluates the authored crease sharpness, OpenSubdiv caps it at
///   the remaining isolation levels.
/// * undiagnosed: refined positions differ and no issue explains it yet.
