//  The test
// ---------------------------------------------------------------------------

#[test]
fn matches_opensubdiv_on_regression_shapes() {
    let dir = data_dir();
    let list = std::fs::read_to_string(dir.join("shapes.txt")).expect("tests/data/upstream");
    let known: BTreeSet<(&str, Check)> = KNOWN_DEVIATIONS.iter().map(|&(s, c, _)| (s, c)).collect();
    assert_eq!(
        known.len(),
        KNOWN_DEVIATIONS.len(),
        "duplicate known deviation"
    );

    // UPSTREAM_SHAPES=a,b restricts the run to those shapes.
    let only = std::env::var("UPSTREAM_SHAPES").ok();
    let names: Vec<&str> = list
        .lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
        .filter(|name| {
            only.as_deref()
                .is_none_or(|o| o.split(',').any(|s| s == *name))
        })
        .collect();
    assert!(!names.is_empty(), "no shape selected");

    // The shapes are independent: compare them on all cores.
    let next = AtomicUsize::new(0);
    let results = Mutex::new(Vec::new());
    let threads = std::thread::available_parallelism().map_or(1, |n| n.get());
    std::thread::scope(|scope| {
        for _ in 0..threads.min(names.len()) {
            scope.spawn(|| loop {
                let i = next.fetch_add(1, Ordering::Relaxed);
                let Some(&name) = names.get(i) else { break };
                let read =
                    |ext: &str| std::fs::read_to_string(dir.join(format!("{name}.{ext}"))).unwrap();
                let mesh = Mesh::parse(&read("mesh"));
                let reference = read("ref");
                let findings = std::panic::catch_unwind(|| compare_shape(&mesh, &reference))
                    .unwrap_or_else(|_| Findings::from([(Create, "panicked".to_string())]));
                results.lock().unwrap().push((i, name, findings));
            });
        }
    });
    let mut results = results.into_inner().unwrap();
    results.sort_by_key(|&(i, _, _)| i);

    let mut unexpected = Vec::new();
    let mut fixed = Vec::new();
    for (_, name, findings) in &results {
        for (check, detail) in findings {
            if !known.contains(&(*name, *check)) {
                unexpected.push(format!("    (\"{name}\", {check:?}, \"\"), // {detail}"));
            }
        }
        for &(shape, check, why) in KNOWN_DEVIATIONS {
            // A failed Create skips every other check of the shape.
            let skipped = findings.contains_key(&Create) && check != Create;
            if shape == *name && !findings.contains_key(&check) && !skipped {
                fixed.push(format!("    (\"{shape}\", {check:?}, \"{why}\")"));
            }
        }
    }

    let mut message = String::new();
    if !unexpected.is_empty() {
        let _ = writeln!(
            message,
            "{} differences from OpenSubdiv are not in KNOWN_DEVIATIONS:\n{}",
            unexpected.len(),
            unexpected.join("\n")
        );
    }
    if !fixed.is_empty() {
        let _ = writeln!(
            message,
            "{} known deviations no longer occur; remove them from KNOWN_DEVIATIONS:\n{}",
            fixed.len(),
            fixed.join("\n")
        );
    }
    assert!(message.is_empty(), "{message}");
}
